const metricas = $('Agregar metricas del dia').first().json;
const muestreo = $('Muestreo aleatorio de aprobadas (10%)').first().json;

return [{
  json: {
    fecha: new Date().toISOString().slice(0, 10),
    totalEvaluadas: Number(metricas.total_evaluadas),
    aprobadas: Number(metricas.aprobadas),
    defectuosas: Number(metricas.defectuosas),
    muestreoAleatorioDeAprobadas: {
      tamanoMuestra: muestreo.tamanoMuestra,
      tasaMuestreo: muestreo.tasaMuestreo,
      conversaciones: muestreo.muestra,
      nota: 'Estas conversaciones fueron aprobadas por el evaluador automatico y elegidas al azar para REVISION HUMANA obligatoria (no una segunda pasada del mismo evaluador): es el control que rompe la circularidad de un evaluador de IA que valida sus propios errores sistematicos (informe etico-regulatorio, 3.1.5.E).',
    },
    estado: 'listo_para_envio',
    generadoEn: new Date().toISOString(),
  },
}];

